): string {
	const base = validateProxyTargetBaseUrl(targetBaseUrl, options);
	const baseHref = base.href.replace(/\/+$/, "");
	const relativePath = proxyPath.replace(/^\/+/, "");
	return new URL(`${baseHref}/${relativePath}`).toString();
